# The default cross-platform benchmark: runs the three portable ONNX models this
# project ships -- Whisper tiny.en (ASR), the Text Scam Classifier (TSC), and the
# FakeAudio / Generated Audio Detector -- through the SAME C++ app on the SAME
# ONNX Runtime, so one command produces a comparable picture on any box (x64 or
# arm64, CPU / GPU / NPU).
#
# Whisper goes through the app's transcribe path (onnx-static backend); the two
# classifiers go through --classify, replaying the pre-baked, validated fixture
# tensors from tools/fixtures/generate.py. Fixtures are auto-generated
# on first run (needs the artifacts/venv + the deepfake models present).
#
# Dependency policy: everything here comes from the configured HF model repo.
# Whisper (tools/fetch/get-models.ps1) needs no Python
# to run. The classifier models also come from HF (tools/fetch/get-classifier-models.ps1
# pulls the deepfake/* subtree), but their input fixtures are generated by the Python
# artifacts/venv (dump_fixtures.py) since the C++ app doesn't tokenize/embed. When the artifacts/venv or
# those models are absent this script SKIPS the classifiers and still runs the full
# HF-hosted Whisper matrix -- so a plain HF checkout benchmarks Whisper end to end.
#
# EP default: the portable vendor-neutral fallback chain (`-Provider auto`).
# To force Intel's bundled OpenVINO EP, pass `-Provider openvino`; every device then
# maps to its OpenVINO target (cpu -> openvino:CPU, gpu -> openvino:GPU,
# npu -> openvino:NPU) through the ABI-isolated build/<platform>-ovep tree. Any
# explicit EP name is honored verbatim (for example DmlExecutionProvider or
# VitisAIExecutionProvider) and fails rather than silently changing providers.
#
#   .\benchmark\run-suite.ps1                       # portable auto-provider matrix
#   .\benchmark\run-suite.ps1 -Provider openvino -Device npu
#   .\benchmark\run-suite.ps1 -Provider openvino -Device npu,gpu,cpu
#   .\benchmark\run-suite.ps1 -Provider auto -Device npu
#   .\benchmark\run-suite.ps1 -Runtime winml -Device npu,gpu,cpu
#   .\benchmark\run-suite.ps1 -Device gpu -Provider DmlExecutionProvider
#   .\benchmark\run-suite.ps1 -Precision preferred  # let each executor choose precision
#   .\run-benchmark.ps1 -Executor fastest -Only whisper
#   .\run-benchmark.ps1 -Executor most-accurate -Only whisper -Device npu,gpu,cpu
#   .\benchmark\run-suite.ps1 -Only whisper         # just the ASR model
#   .\benchmark\run-suite.ps1 -RegenerateFixtures   # rebuild classifier fixtures first
#
# Startup policy: every model/device gets a dedicated cache that is deleted before
# the run. The C++ harness then creates the session twice against that cache:
# cold = compile from an empty cache; hot = reload the artifact cold just produced.
#
# Repetition policy: accuracy-quick defaults to one measured inference per clip
# or fixture. Latency defaults to 10 measured Whisper transcriptions per clip and
# 20 classifier inferences per fixture. -Runs and -ClassifierRuns override either
# mode explicitly.

[CmdletBinding()]
param(
    [ValidateSet("npu", "gpu", "cpu")][string[]]$Device = @("npu", "gpu", "cpu"),
    [ValidateSet("whisper", "tsc", "fakeaudio", "all")][string[]]$Only = @("all"),
    [ValidateSet("accuracy-quick", "latency")][string]$Mode = "accuracy-quick",
    [string[]]$Profile = @("all"),
    [ValidateRange(1, 1000)]
    [int]$Runs = 1,
    [ValidateRange(1, 1000)]
    [int]$ClassifierRuns = 1,
    [string]$Configuration = "Release",
    [string]$Provider = "auto",
    [ValidateSet("all", "bundled", "winml")][string]$Runtime = "all",
    [ValidateSet("default", "f32", "f16", "bf16", "preferred")]
    [string]$Precision = "default",
    [string]$Audio = "",
    [string]$Results = "",
    [string]$ClassifierResults = "",
    [string]$Manifest = "",
    [string]$AttemptLedger = "",
    [string]$AccuracyLedger = "",
    [string]$RunnerManifest = "",
    [string]$RunnerId = "",
    [ValidateSet("", "fastest", "most-accurate")][string]$Executor = "",
    [switch]$ExplainRunnerSelection,
    [switch]$RegenerateFixtures,
    [switch]$NoResults
)

$ErrorActionPreference = "Stop"
. (Join-Path $PSScriptRoot "lib\harness.ps1")
Initialize-BenchmarkConsole

$runsExplicit = $PSBoundParameters.ContainsKey("Runs")
$classifierRunsExplicit = $PSBoundParameters.ContainsKey("ClassifierRuns")
if ($Mode -eq "latency") {
    if (-not $runsExplicit) { $Runs = 10 }
    if (-not $classifierRunsExplicit) { $ClassifierRuns = 20 }
}

# "auto" is the escape hatch back to the app's portable per-device EP fallback chain
# (leave --provider off so ort_ep.hpp walks VitisAI/QNN/DirectML/OpenVINO/CPU).
if ($Provider -eq "auto") { $Provider = "" }
if ($Runtime -eq "winml") {
    # Windows ML maps -Device to PREFER_NPU/GPU/CPU. Leave --provider unset so
    # ORT's policy selector can choose among the catalog-registered EP devices.
    $Provider = ""
}
if ($Precision -ne "default") {
    $env:NPU_INFERENCE_BENCH_PRECISION = $Precision
}

$root = Split-Path $PSScriptRoot -Parent
$hostArch = if ([System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture -eq [System.Runtime.InteropServices.Architecture]::Arm64) { "ARM64" } else { "x64" }
$hardware = Get-BenchmarkHardware
$hostVendor = [string]$hardware.cpu.vendor
$runnerPackage = $null
if ($RunnerManifest) {
    $runnerPackage = Get-BenchmarkRunnerPackageManifest -Path $RunnerManifest
}
if ($Executor -and -not $runnerPackage) {
    Write-Host "-Executor requires -RunnerManifest (package mode)." -ForegroundColor Red
    exit 1
}
if ($Executor -and $RunnerId) {
    Write-Host "-Executor and -RunnerId are mutually exclusive." -ForegroundColor Red
    exit 1
}
$bundledTag = switch ($hostVendor) {
    'AMD'      { "$hostArch-amd" }
    'Qualcomm' { "$hostArch-qualcomm" }
    default    { $hostArch }
}

if ($Executor) {
    $selection = Invoke-BenchmarkExecutorSelection `
        -Objective $Executor `
        -PackageManifest $runnerPackage `
        -SuiteScript $PSCommandPath `
        -Root $root `
        -Device $Device `
        -Only $Only `
        -Profile $Profile `
        -HostVendor $hostVendor `
        -HostArchitecture $hostArch `
        -Runtime $Runtime `
        -Provider $Provider `
        -Configuration $Configuration `
        -Precision $Precision `
        -Manifest $Manifest
    if (-not $selection.winner) { exit 1 }
    exit 0
}

function Get-RequestedBenchmarkTags {
    param([Parameter(Mandatory)][string]$RuntimeName)

    $manifestPath = if ($Manifest) { $Manifest } else { Join-Path $root "benchmark\manifests\portable.json" }
    if (-not (Test-Path -LiteralPath $manifestPath)) {
        return @("$RuntimeName/<manifest-unavailable>")
    }
    $requested = if ($Only -contains "all") { @("whisper", "tsc", "fakeaudio") } else { @($Only) }
    $hostVendor = [string](Get-BenchmarkHardware).cpu.vendor
    $manifestWorkloads = @((Get-Content -LiteralPath $manifestPath -Raw -Encoding UTF8 |
        ConvertFrom-Json).workloads)
    $tags = [Collections.Generic.List[string]]::new()
    foreach ($dev in $Device) {
        foreach ($workload in $manifestWorkloads) {
            $selector = if ($workload.kind -eq "asr") { "whisper" } else { [string]$workload.id }
            if ($requested -notcontains $selector) { continue }
            $profiles = @(Get-BenchmarkExecutionProfiles -Workload $workload -Device $dev `
                -Selectors $Profile -HostVendor $hostVendor)
            foreach ($executionProfile in $profiles) {
                $tags.Add("$RuntimeName/$($workload.id)/$($executionProfile.id)/$dev")
            }
        }
    }
    return @($tags)
}

function Write-MissingRuntimeRuns {
    param(
        [Parameter(Mandatory)][string]$RuntimeName,
        [Parameter(Mandatory)][string]$Executable
    )
    Write-Host "NOT PERFORMED: runtime '$RuntimeName' is unavailable." -ForegroundColor Yellow
    Write-Host "  missing prerequisite: $Executable" -ForegroundColor Yellow
    foreach ($tag in @(Get-RequestedBenchmarkTags -RuntimeName $RuntimeName)) {
        Write-Host "  - $tag" -ForegroundColor DarkYellow
    }
}

if ($Runtime -eq "all") {
    $runtimeFailures = 0
    foreach ($targetRuntime in @("bundled", "winml")) {
        if ($runnerPackage) {
            try {
                $null = Resolve-BenchmarkRunnerPack -PackageManifest $runnerPackage `
                    -Runtime $targetRuntime -Provider $Provider -RunnerId $RunnerId `
                    -HostVendor $hostVendor -HostArchitecture $hostArch
            } catch {
                Write-Host "NOT PERFORMED: runtime '$targetRuntime' is unavailable." -ForegroundColor Yellow
                Write-Host "  missing prerequisite: $($_.Exception.Message)" -ForegroundColor Yellow
                foreach ($tag in @(Get-RequestedBenchmarkTags -RuntimeName $targetRuntime)) {
                    Write-Host "  - $tag" -ForegroundColor DarkYellow
                }
                if ($targetRuntime -eq "bundled") {
                    $runtimeFailures++
                }
                continue
            }
        } else {
            $targetTag = if ($targetRuntime -eq "winml") { "$hostArch-winml" } else { $bundledTag }
            $targetExe = Join-Path $root "artifacts\build\$targetTag\$Configuration\NpuInferenceBench.exe"
            if (-not (Test-Path -LiteralPath $targetExe)) {
                Write-MissingRuntimeRuns -RuntimeName $targetRuntime -Executable $targetExe
                continue
            }
        }
        $childArgs = @{
            Runtime = $targetRuntime; Device = $Device; Only = $Only; Mode = $Mode
            Profile = $Profile; Runs = $Runs; ClassifierRuns = $ClassifierRuns
            Configuration = $Configuration; Provider = $Provider; Precision = $Precision
        }
        foreach ($pair in @(
            @("Audio", $Audio), @("Results", $Results), @("ClassifierResults", $ClassifierResults),
            @("Manifest", $Manifest), @("AttemptLedger", $AttemptLedger), @("AccuracyLedger", $AccuracyLedger),
            @("RunnerId", $RunnerId)
        )) {
            if ($pair[1]) { $childArgs[$pair[0]] = $pair[1] }
        }
        if ($RunnerManifest) { $childArgs.RunnerManifest = $RunnerManifest }
        if ($ExplainRunnerSelection) { $childArgs.ExplainRunnerSelection = $true }
        if ($RegenerateFixtures) { $childArgs.RegenerateFixtures = $true }
        if ($NoResults) { $childArgs.NoResults = $true }
        & $PSCommandPath @childArgs
        if ($LASTEXITCODE -ne 0) { $runtimeFailures++ }
    }
    if ($runtimeFailures) { exit 1 }
    exit 0
}

# Target the HOST architecture's build tree by default: x64 boxes get build\x64\,
# ARM64 (Snapdragon) boxes get build\ARM64\. Use OSArchitecture so this is correct
# whether PowerShell runs native or x64-emulated on ARM64.
$platform = $bundledTag
$runnerIsolationRoot = ""
$selectedRunnerId = ""
if ($runnerPackage) {
    try {
        $selectedRunner = Resolve-BenchmarkRunnerPack -PackageManifest $runnerPackage `
            -Runtime $Runtime -Provider $Provider -RunnerId $RunnerId `
            -HostVendor $hostVendor -HostArchitecture $hostArch
    } catch {
        Write-Host $_.Exception.Message -ForegroundColor Red
        exit 1
    }
    $exe = $selectedRunner.exe
    $platform = $selectedRunner.platform_tag
    $runnerIsolationRoot = $selectedRunner.root
    $selectedRunnerId = $selectedRunner.id
    Write-Host ("runner     : {0} -> {1}" -f $selectedRunnerId, $exe) -ForegroundColor Cyan
    if ($ExplainRunnerSelection) {
        Write-Host ("selection  : runtime={0}, provider={1}, vendor={2}, architecture={3}, platform={4}" -f
            $Runtime, $(if ($Provider) { $Provider } else { "auto" }),
            $hostVendor, $hostArch, $platform)
        exit 0
    }
} else {
    # Development-tree selection retains the historical build/<tag> behavior.
    if ($Runtime -eq "winml") {
        $platform = "$hostArch-winml"
    }
    elseif ($Provider -like "openvino*") {
        $ovepExe = Join-Path $root "artifacts\build\$hostArch-ovep\$Configuration\NpuInferenceBench.exe"
        if (Test-Path $ovepExe) {
            $platform = "$hostArch-ovep"
        }
        else {
            Write-Host "OpenVINO EP requested ('$Provider') but no OVEP build at build\$hostArch-ovep\$Configuration." -ForegroundColor Red
            if ($hostArch -eq "ARM64") {
                Write-Host "  OpenVINO has no ARM64 EP build; use -Provider auto for the QNN path." -ForegroundColor Red
            }
            else {
                Write-Host "  -> build it with: .\tools\setup\setup-ovep.ps1; .\tools\build\build.ps1 -EnableOvep" -ForegroundColor Red
            }
            exit 1
        }
    }
    elseif ($Provider -match "(?i)dml|directml") {
        $dmlExe = Join-Path $root "artifacts\build\$hostArch-dml\$Configuration\NpuInferenceBench.exe"
        if (Test-Path $dmlExe) {
            $platform = "$hostArch-dml"
        }
        else {
            Write-Host "No dedicated DirectML build at build\$hostArch-dml\$Configuration; trying the plain ORT build." -ForegroundColor Yellow
        }
    }
    $exe = Join-Path $root "artifacts\build\$platform\$Configuration\NpuInferenceBench.exe"
    if (-not (Test-Path $exe)) {
        Write-MissingRuntimeRuns -RuntimeName $Runtime -Executable $exe
        if ($Runtime -eq "winml") {
            Write-Host "Not built: $exe  (run .\tools\setup\setup-winml.ps1; .\tools\build\build.ps1 -EnableWinML -DisableIntel)" -ForegroundColor Red
        }
        else {
            Write-Host "Not built: $exe  (run .\tools\build\build.ps1 -EnableOrt / -EnableDirectML / -EnableOvep or bootstrap.ps1)" -ForegroundColor Red
        }
        exit 1
    }
}

if ($Only -contains "all") { $Only = @("whisper", "tsc", "fakeaudio") }
if (-not $Results) { $Results = Join-Path $root "results\ledgers\asr.csv" }
if (-not $ClassifierResults) { $ClassifierResults = Join-Path $root "results\ledgers\classifiers.csv" }
if (-not $AttemptLedger) { $AttemptLedger = Join-Path $root "results\ledgers\attempts.jsonl" }
$accuracyLedgerExplicit = [bool]$AccuracyLedger
if (-not $Manifest) { $Manifest = Join-Path $root "benchmark\manifests\portable.json" }
$audioExplicit = [bool]$Audio
if (-not $Audio) { $Audio = Join-Path $root "artifacts\workloads\speech\ls_000.wav" }

if (-not (Test-Path $Manifest)) {
    Write-Host "Benchmark manifest missing: $Manifest" -ForegroundColor Red
    exit 1
}
$workloads = @((Get-Content $Manifest -Raw -Encoding UTF8 | ConvertFrom-Json).workloads)
$environmentSnapshot = Get-BenchmarkEnvironmentSnapshot `
    -Root $root -Exe $exe -RuntimeTarget $Runtime -BuildTree $platform `
    -RunnerId $selectedRunnerId
Write-Host "environment: $($environmentSnapshot.id) -> $($environmentSnapshot.path)" -ForegroundColor DarkCyan
if ($Mode -eq "accuracy-quick" -and -not $accuracyLedgerExplicit) {
    $accuracyRunDir = Join-Path $root "results\accuracy-runs"
    New-Item -ItemType Directory -Force -Path $accuracyRunDir | Out-Null
    $AccuracyLedger = Join-Path $accuracyRunDir "$($environmentSnapshot.id).jsonl"
    if (Test-Path -LiteralPath $AccuracyLedger) {
        throw "Immutable accuracy run already exists: $AccuracyLedger"
    }
}
# Classifier fixtures + ONNX models are colocated under artifacts/workloads/classifiers/
# (model.tsv paths are fixture-relative, e.g. ../../fakeaudio/model.onnx).
$fixRoot = Join-Path $root "artifacts\workloads\classifiers\fixtures"
$classifierFix = @{ tsc = (Join-Path $fixRoot "tsc"); fakeaudio = (Join-Path $fixRoot "fakeaudio") }

$providerTag = if ($Provider) { $Provider } else { "auto" }
Write-Host "repetitions: Whisper=$Runs per clip; classifiers=$ClassifierRuns per fixture" -ForegroundColor DarkCyan

$ran = @()
$skipped = @()
$script:prerequisiteSkips = @()

$wantClassifiers = @($Only | Where-Object { $_ -in @("tsc", "fakeaudio") })
if ($wantClassifiers.Count -gt 0) {
    Ensure-BenchmarkClassifierFixtures -Root $root -FixtureDirectories $classifierFix `
        -Models $wantClassifiers -Regenerate:$RegenerateFixtures
}

foreach ($dev in $Device) {
    Write-Host "`n==================== device: $dev ====================" -ForegroundColor Magenta

    foreach ($workload in $workloads) {
        $selector = if ($workload.kind -eq "asr") { "whisper" } else { [string]$workload.id }
        if ($Only -notcontains $selector) { continue }
        $profiles = @(Get-BenchmarkExecutionProfiles -Workload $workload -Device $dev `
            -Selectors $Profile -HostVendor $hostVendor)
        if (-not $profiles.Count) {
            $profileLabel = if ($Profile -contains "all") { "no-valid-profile" } else { $Profile -join "," }
            $unsupportedProfile = [pscustomobject]@{
                id = $profileLabel; graphRole = ""; accuracyEligible = $false
            }
            $message = "no selected execution profile supports '$($workload.id)' on $hostVendor $dev"
            Write-Host $message -ForegroundColor DarkYellow
            Write-SuiteAttempt $workload $unsupportedProfile $dev "unsupported" $message $null
            $skipped += "$($workload.id)/$profileLabel/$dev"
            continue
        }
        foreach ($executionProfile in $profiles) {
            $tag = "$($workload.id)/$($executionProfile.id)/$dev"
            Write-Host "`n--- $($workload.id) [$($executionProfile.id), $($workload.kind)] ---" -ForegroundColor Cyan
            if (Invoke-NativeBenchmark $workload $executionProfile $dev) {
                $ran += $tag
            } else {
                $skipped += $tag
            }
        }
    }
}

$publishedAttempts = Write-BenchmarkRunAttemptSnapshot -Root $root `
    -RollingLedger $AttemptLedger -EnvironmentSnapshotId $environmentSnapshot.id

Write-Host "`n==================== summary ====================" -ForegroundColor Magenta
Write-Host "ran    : $(if ($ran.Count) { $ran -join ', ' } else { '(nothing)' })" -ForegroundColor Green
if ($skipped.Count) { Write-Host "skipped: $($skipped -join ', ')" -ForegroundColor Yellow }
if ($script:prerequisiteSkips.Count) {
    Write-Host "NOT PERFORMED (missing prerequisites):" -ForegroundColor Yellow
    foreach ($skip in $script:prerequisiteSkips) {
        Write-Host "  - $($skip.tag) [$($skip.status)]: $($skip.reason)" -ForegroundColor DarkYellow
    }
}
if ($Mode -eq "latency" -and -not $NoResults) {
    Write-Host "ASR ledger        : $Results" -ForegroundColor DarkGray
    Write-Host "classifier ledger : $ClassifierResults" -ForegroundColor DarkGray
}
if ($Mode -eq "accuracy-quick") {
    Write-Host "accuracy run      : $AccuracyLedger" -ForegroundColor DarkGray
}
Write-Host "attempt ledger    : $AttemptLedger" -ForegroundColor DarkGray
Write-Host "published attempts: $($publishedAttempts.path) ($($publishedAttempts.count) records)" -ForegroundColor DarkGray
